mapper.select:
SELECT m.session_id AS session_id,
       m.agent_id AS agent_id,
       m.mac_address AS mac_address,
       d.province AS province,
       m.content AS content
FROM ai_agent_chat_history m
LEFT JOIN ai_device d ON d.mac_address = m.mac_address

  m.chat_type = 1

    AND m.agent_id IN
    #{id}


    AND m.agent_id = #{q.agentId}


    AND m.mac_address = #{q.macAddress}


    AND d.province = #{q.province}


    AND m.created_at >= #{q.startTime}


    AND m.created_at <= #{q.endTime}


ORDER BY m.created_at DESC, m.id DESC
LIMIT #{q.limit}
